import json, pathlib
base = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/php_oracle/manifests/streams/php-8.5.6')
names = ["GLOB_ERR","GLOB_MARK","GLOB_NOCHECK","GLOB_NOSORT","GLOB_BRACE","GLOB_NOESCAPE","GLOB_ONLYDIR","GLOB_AVAILABLE_FLAGS"]
for target in sorted(p.name for p in base.iterdir() if p.is_dir()):
    f = next(iter((base / target).glob('*.json')), None)
    if not f:
        continue
    data = json.loads(f.read_text())
    found = {}
    def walk(node):
        if isinstance(node, dict):
            for k, v in node.items():
                if k in names:
                    found[k] = v
                walk(v)
        elif isinstance(node, list):
            for v in node:
                walk(v)
    walk(data)
    print(f'{target}:')
    for n in names:
        if n in found:
            v = found[n]
            v = v.get('value') if isinstance(v, dict) else v
            print(f'    {n:24s} {v}')
